## After — ComponentResource with Aliases

```typescript
// src/index.ts (after migration)
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { WebApp } from "./components/webapp";

const config = new pulumi.Config();

// The component encapsulates all infrastructure.
// Each resource inside receives an `aliases` array that maps
// its old flat-scope URN so Pulumi recognizes it as the same resource.
const infra = new WebApp("infra", {
    environment: config.require("environment"),
    region: config.require("region"),
    accountId: config.require("accountId"),
    dbPassword: config.requireSecret("dbPassword"),
});

// ─── Outputs (unchanged — still exported from the program root) ───────
export const clusterEndpoint = infra.clusterEndpoint;
export const bucketName = infra.bucketName;
export const dbEndpoint = infra.dbEndpoint;
export const serviceRoleArn = infra.serviceRoleArn;
```

```typescript
// src/components/webapp.ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface WebAppArgs {
    environment: string;
    region: string;
    accountId: string;
    dbPassword: pulumi.Input<string>;
}

export interface WebAppState extends pulumi.ComponentResource {
    clusterEndpoint: pulumi.Output<string>;
    bucketName: pulumi.Output<string>;
    dbEndpoint: pulumi.Output<string>;
    serviceRoleArn: pulumi.Output<string>;
}

export class WebApp extends pulumi.ComponentResource implements WebAppState {
    clusterEndpoint!: pulumi.Output<string>;
    bucketName!: pulumi.Output<string>;
    dbEndpoint!: pulumi.Output<string>;
    serviceRoleArn!: pulumi.Output<string>;

    constructor(name: string, args: WebAppArgs, opts?: pulumi.ComponentResourceOptions) {
        super("myorg:components:WebApp", name, args, opts);

        const { environment, region, accountId, dbPassword } = args;
        const az = `${region}a`;

        // ─── VPC ───────────────────────────────────────────────────────
        const vpc = new aws.ec2.Vpc("app-vpc", {
            cidrBlock: "10.0.0.0/16",
            enableDnsSupport: true,
            enableDnsHostnames: true,
            tags: { Name: `app-vpc-${environment}` },
        }, {
            parent: this,
            // Alias: the old flat-scope URN. Pulumi will match the existing
            // resource in state to this new identity without replacement.
            aliases: [`aws:ec2/v2:Vpc:app-vpc`],
        });

        const publicSubnet = new aws.ec2.Subnet("public-subnet", {
            vpcId: vpc.id,
            cidrBlock: "10.0.1.0/24",
            availabilityZone: az,
            mapPublicIpOnLaunch: true,
            tags: { Name: `public-${environment}` },
        }, {
            parent: this,
            aliases: [`aws:ec2/v2:Subnet:public-subnet`],
        });

        const privateSubnet = new aws.ec2.Subnet("private-subnet", {
            vpcId: vpc.id,
            cidrBlock: "10.0.2.0/24",
            availabilityZone: az,
            tags: { Name: `private-${environment}` },
        }, {
            parent: this,
            aliases: [`aws:ec2/v2:Subnet:private-subnet`],
        });

        // ─── EKS ───────────────────────────────────────────────────────
        const eksRole = new aws.iam.Role("eks-role", {
            assumeRolePolicy: aws.iam.getPolicyDocument({
                json: JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Service: "eks.amazonaws.com" },
                        Action: "sts:AssumeRole",
                    }],
                }),
            }).then((d) => d.json),
        }, {
            parent: this,
            aliases: [`aws:iam/v4:Role:eks-role`],
        });

        const cluster = new aws.eks.Cluster("eks-cluster", {
            roleArn: eksRole.arn,
            version: "1.29",
            vpcConfig: {
                subnetIds: [publicSubnet.id, privateSubnet.id],
                endpointPrivateAccess: true,
                endpointPublicAccess: environment === "prod",
            },
            tags: { Name: `eks-${environment}` },
        }, {
            parent: this,
            aliases: [`aws:eks/v1:Cluster:eks-cluster`],
        });

        const nodeGroupConfig = environment === "dev"
            ? { instanceTypes: ["t3.medium"], minSize: 2, maxSize: 2, desiredSize: 2 }
            : { instanceTypes: ["t3.large"], minSize: 4, maxSize: 4, desiredSize: 4 };

        const nodeGroup = new aws.eks.NodeGroup("node-group", {
            clusterName: cluster.name,
            instanceTypes: nodeGroupConfig.instanceTypes,
            minSize: nodeGroupConfig.minSize,
            maxSize: nodeGroupConfig.maxSize,
            desiredSize: nodeGroupConfig.desiredSize,
            subnetIds: [privateSubnet.id],
            tags: { Name: `ng-${environment}` },
        }, {
            parent: this,
            aliases: [`aws:eks/v1:NodeGroup:node-group`],
        });

        // ─── S3 ────────────────────────────────────────────────────────
        const bucket = new aws.s3.BucketV2("assets-bucket", {
            versioning: { enabled: true },
            tags: { Name: `assets-${environment}` },
        }, {
            parent: this,
            aliases: [`aws:s3/v2:Bucket:assets-bucket`],
        });

        new aws.s3.BucketVersioningV2("bucket-versioning", {
            bucket: bucket.id,
            versioningConfiguration: { status: "Enabled" },
        }, {
            parent: this,
            aliases: [`aws:s3/v2:BucketVersioning:bucket-versioning`],
        });

        new aws.s3.BucketServerSideEncryptionConfigurationV2("bucket-encryption", {
            bucket: bucket.id,
            rules: [{ applyServerSideEncryptionByDefault: { sseAlgorithm: "aws:kms" } }],
        }, {
            parent: this,
            aliases: [`aws:s3/v2:BucketServerSideEncryptionConfiguration:bucket-encryption`],
        });

        new aws.s3.BucketPublicAccessBlock("bucket-public-access", {
            bucket: bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, {
            parent: this,
            aliases: [`aws:s3/v2:BucketPublicAccessBlock:bucket-public-access`],
        });

        if (environment === "prod") {
            const replRole = new aws.iam.Role("repl-role", {
                assumeRolePolicy: aws.iam.getPolicyDocument({
                    json: JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [{
                            Effect: "Allow",
                            Principal: { Service: "s3.amazonaws.com" },
                            Action: "s3:ReplicateObject",
                        }],
                    }),
                }).then((d) => d.json),
            }, {
                parent: this,
                aliases: [`aws:iam/v4:Role:repl-role`],
            });

            new aws.s3.BucketReplicationConfiguration("bucket-replication", {
                bucket: bucket.id,
                role: replRole.arn,
                rules: [{
                    destination: { bucket: pulumi.interpolate`${bucket.id}-repl` },
                    prefix: "",
                }],
            }, {
                parent: this,
                aliases: [`aws:s3/v2:BucketReplicationConfiguration:bucket-replication`],
            });
        }

        // ─── RDS ───────────────────────────────────────────────────────
        const dbSubnetGroup = new aws.rds.SubnetGroup("db-subnet-group", {
            subnetIds: [privateSubnet.id],
            tags: { Name: `db-subnets-${environment}` },
        }, {
            parent: this,
            aliases: [`aws:rds/v4:SubnetGroup:db-subnet-group`],
        });

        const rds = new aws.rds.Instance("postgres", {
            allocatedStorage: environment === "dev" ? 20 : 100,
            dbName: "appdb",
            engine: "postgres",
            engineVersion: "15",
            identifier: `postgres-${environment}`,
            instanceClass: environment === "dev" ? "db.t3.micro" : "db.t3.medium",
            multiAz: environment === "prod",
            storageEncrypted: environment === "prod",
            deletionProtection: true,
            backupRetentionPeriod: 14,
            publiclyAccessible: false,
            subnetGroupName: dbSubnetGroup.name,
            username: "appuser",
            password: dbPassword,
            tags: { Name: `postgres-${environment}` },
        }, {
            parent: this,
            aliases: [`aws:rds/v4:Instance:postgres`],
        });

        // ─── IAM ───────────────────────────────────────────────────────
        const serviceRole = new aws.iam.Role("service-role", {
            assumeRolePolicy: environment === "dev"
                ? aws.iam.getPolicyDocument({
                    json: JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [{
                            Effect: "Allow",
                            Principal: { AWS: `arn:aws:iam::${accountId}:user/ops-bot` },
                            Action: "sts:AssumeRole",
                        }],
                    }),
                }).then((d) => d.json)
                : aws.iam.getPolicyDocument({
                    json: JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [{
                            Effect: "Allow",
                            Principal: { Federated: `arn:aws:iam::${accountId}:oidc-provider/oidc.eks.${region}.amazonaws.com/id/*` },
                            Action: "sts:AssumeRoleWithWebIdentity",
                            Condition: {
                                StringEquals: {
                                    [`oidc.eks.${region}.amazonaws.com/id/*/sub`]: "system:serviceaccount:default:app-sa",
                                },
                            },
                        }],
                    }),
                }).then((d) => d.json),
            tags: { Name: `service-role-${environment}` },
        }, {
            parent: this,
            aliases: [`aws:iam/v4:Role:service-role`],
        });

        const bucketPolicy = new aws.iam.Policy("bucket-policy", {
            name: `assets-policy-${environment}`,
            policy: bucket.id.apply((id) => JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Action: ["s3:GetObject", "s3:PutObject"],
                    Resource: `arn:aws:s3:::${id}/*`,
                }],
            })),
        }, {
            parent: this,
            aliases: [`aws:iam/v4:Policy:bucket-policy`],
        });

        new aws.iam.RolePolicyAttachment("attach-bucket-policy", {
            role: serviceRole.name,
            policyArn: bucketPolicy.arn,
        }, {
            parent: this,
            aliases: [`aws:iam/v4:RolePolicyAttachment:attach-bucket-policy`],
        });

        // ─── Secrets ───────────────────────────────────────────────────
        const secret = new aws.secretsmanager.Secret("db-secret", {
            name: `db-conn-${environment}`,
            description: "DB connection string",
            tags: { Name: `db-secret-${environment}` },
        }, {
            parent: this,
            aliases: [`aws:secretsmanager/v4:Secret:db-secret`],
        });

        // ─── Expose outputs via the component ─────────────────────────
        this.clusterEndpoint = cluster.endpoint;
        this.bucketName = bucket.id;
        this.dbEndpoint = rds.address;
        this.serviceRoleArn = serviceRole.arn;

        // Register all child resources so they are tracked under this component
        this.registerResources("myorg:components:WebApp", {
            vpc, publicSubnet, privateSubnet,
            eksRole, cluster, nodeGroup,
            bucket, rds, dbSubnetGroup,
            serviceRole, bucketPolicy, secret,
        });
    }
}
```

---

## How `aliases` Works

```
┌─────────────────────────────────────────────────────────────────────────────┐
│  pulumi up (first run after migration)                                      │
├─────────────────────────────────────────────────────────────────────────────┤
│                                                                             │
│  State has:  urn:pulumi:dev::webapp::aws:s3/v2:Bucket::assets-bucket        │
│                                                                             │
│  Program declares:                                                          │
│    type:  aws:s3/v2:Bucket                                                  │
│    name:  assets-bucket                                                     │
│    parent: myorg:components:WebApp::infra                                   │
│    → new URN: urn:pulumi:dev::webapp::myorg:components:WebApp::infra::      │
│               aws:s3/v2:Bucket::assets-bucket                                │
│                                                                             │
│  aliases: ["aws:s3/v2:Bucket:assets-bucket"]                                │
│    → Pulumi checks: does state contain a resource matching                  │
│      type=aws:s3/v2:Bucket, name=assets-bucket, in the OLD flat scope?      │
│    → YES → no replacement. The resource is adopted under its new URN.       │
│                                                                             │
└─────────────────────────────────────────────────────────────────────────────┘
```

### Alias format

```
<typeToken>:<logicalName>
```

This is a **partial URN** — Pulumi resolves it against the current project/stack, so you don't need the full `urn:pulumi:stack::project::...` prefix.

### When to remove aliases

After the first successful `pulumi up` post-migration, the state file has been updated to the new URN. You can then safely remove the `aliases` arrays in a subsequent commit. They are only needed for the **one transition**.

---

## Verification

```bash
# Dry run — should show ZERO replaces, only the component registration
pulumi preview --stack dev

# Expected output:
#  ~ updating webapp:infra: myorg:components:WebApp (infra) [urn=...]
#  1 unchanged, 1 updated
#
# If you see "replace" → an alias is missing or mistyped.
```

To audit which resources would be replaced:

```bash
pulumi preview --stack dev --diff 2>&1 | grep -i "replace"
```

---

## Common Mistakes

| Mistake | Symptom | Fix |
|---------|---------|-----|
| Alias type token has wrong version (e.g. `aws:s3:Bucket` instead of `aws:s3/v2:Bucket`) | Replacement | Match the **exact** type token from `pulumi stack export` |
| Alias name doesn't match the old logical name | Replacement | Use `pulumi stack export \| jq '.crd.version.resources[] \| select(.type \| contains("Bucket")) \| .urn'` to get the exact name |
| Forgot `parent: this` on a child resource | Resource not tracked under component (harmless for aliases but breaks encapsulation) | Add `parent: this` to every `opts` object |
| Alias present on a resource that **didn't exist** in the old flat program | No-op (harmless) | Safe to include for resources that are conditional (e.g. prod-only replication) |

---

## Extracting Old URNs from State

If you're unsure of the exact type tokens and names:

```bash
pulumi stack export --stack dev | jq '.crd.version.resources[] | {type: .type, name: .urn | split("::")[-1]}'
```

Example output:

```json
{"type": "aws:s3/v2:Bucket", "name": "assets-bucket"}
{"type": "aws:eks/v1:Cluster", "name": "eks-cluster"}
{"type": "aws:rds/v4:Instance", "name": "postgres"}
```

Use these verbatim as your `aliases` values.
